private theorem scaleWeight_far {L u : ℝ} (hL : 32 ≤ L)
    (hu : u < L / 2 ∨ 2 * L < u) :
    scaleWeight L u ≤ Real.exp (-(L ^ 2 / 8)) * Real.exp (-((u - L) ^ 2 / 2))

